#!/usr/bin/env python3
"""Report Python functions that a diff adds or edits without full annotations.

The annotation rules mirror ruff's ANN001, ANN201, ANN202 and ANN204, which
products/ruff.toml enforces file-wide. This check applies them only to the
functions a diff touches, so old code is held to the rule one function at a time.

Usage:
  check_touched_typing.py --staged
  check_touched_typing.py --base <rev> --report <path> [--github] [--blocking-from <YYYY-MM-DD>]
  check_touched_typing.py --enforce <report>
"""

from __future__ import annotations

import re
import ast
import sys
import json
import argparse
import subprocess
from collections.abc import Callable
from dataclasses import asdict, dataclass, field
from datetime import UTC, date, datetime
from pathlib import PurePosixPath
from typing import TextIO

CHECKED_ROOTS = ("posthog", "ee", "products", "common")
# The same folders products/ruff.toml exempts from the annotation rules, plus fixtures and vendored code.
SKIPPED_PARTS = frozenset(
    {
        "tests",
        "test",
        "__tests__",
        "migrations",
        "clickhouse_migrations",
        "management",
        "skills",
        "eval",
        "evals",
        "dags",
        "scripts",
        "stats",
        "fixtures",
        "vendor",
    }
)
# Matched against the leading comment lines only, so a docstring that says "generated by" does not skip a file.
GENERATED_HEADER = re.compile(r"do not edit|auto-?generated|automatically generated|generated by|@generated", re.I)
# "Any" followed by a lowercase word is prose, as in "Any team member".
ANY_TOKEN = re.compile(r"\bAny\b(?!\s+[a-z])")
IGNORE_COMMENT = re.compile(r"#\s*(type|ty|pyright)\s*:\s*ignore")
# ruff honors these exemptions, so the check does too: a file-wide noqa, or a noqa on the flagged line.
# Without codes they exempt every rule. With codes they exempt only the rules they list.
FILE_NOQA = re.compile(r"^#\s*(?:ruff|flake8)\s*:\s*noqa(?::\s*(?P<codes>[A-Z0-9, ]+))?", re.M | re.I)
LINE_NOQA = re.compile(r"#\s*noqa(?::\s*(?P<codes>[A-Z0-9, ]+))?", re.I)
ALL_RULES = frozenset({"ANN001", "ANN201", "ANN202", "ANN204"})
REMOVED_DEF = re.compile(r"^\s*(?:async\s+)?def\s+(\w+)")
HUNK_HEADER = re.compile(r"^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@")
MAX_LISTED = 10
MAX_SECTION_ROWS = 50
# The same characters markdownCell in frontend/bin/ci-report/format.mjs strips.
MARKDOWN_CELL_UNSAFE = re.compile(r"[`|\x00-\x1f\x7f]")


@dataclass(frozen=False)
class FileChange:
    path: str
    is_new: bool = False
    is_deleted: bool = False
    added: dict[int, str] = field(default_factory=dict)
    removed: list[str] = field(default_factory=list)
    # For each hunk that only deletes lines: the new-side line the deleted lines followed.
    deleted_after: list[int] = field(default_factory=list)


@dataclass(frozen=True)
class Finding:
    path: str
    line: int
    name: str
    kind: str
    missing: list[str]


def is_blocking(blocking_from: date) -> bool:
    return datetime.now(UTC).date() >= blocking_from


def markdown_cell(value: str) -> str:
    return MARKDOWN_CELL_UNSAFE.sub("", value)


@dataclass(frozen=True)
class Report:
    findings: list[Finding]
    any_delta: int
    ignore_delta: int
    unparsed: list[str] = field(default_factory=list)

    @property
    def new_file_findings(self) -> list[Finding]:
        return [f for f in self.findings if f.kind == "new file"]

    def ci_section(self, blocking_from: date | None) -> dict[str, str] | None:
        """The CI report section as postSection takes it, or None when there is nothing to report."""
        if not self.findings and self.any_delta <= 0 and self.ignore_delta <= 0:
            return None
        outcome = "fails the Python code quality job"
        if blocking_from and not is_blocking(blocking_from):
            outcome += f" from {blocking_from.isoformat()}"

        count = len(self.findings)
        new_file_count = len(self.new_file_findings)
        summary = []
        if count:
            summary.append(f"{count} touched function{'s' if count != 1 else ''} without full annotations")
        if self.any_delta > 0:
            summary.append(f"+{self.any_delta} Any")
        if self.ignore_delta > 0:
            summary.append(f"+{self.ignore_delta} type ignore{'s' if self.ignore_delta != 1 else ''}")

        body = [
            "Functions this PR adds or edits must annotate every parameter and the return type "
            "(the rules of ruff ANN001, ANN201, ANN202 and ANN204).",
        ]
        if new_file_count:
            where = (
                "1 of them is in a new file" if new_file_count == 1 else f"{new_file_count} of them are in new files"
            )
            body.append(f"**{where}**, which {outcome}. The rest is a warning.")
        else:
            body.append(f"An untyped function in a new file {outcome}. The rest is a warning.")
        body.append("")
        if count:
            body += ["| Function | Location | Kind | Missing |", "| --- | --- | --- | --- |"]
            for f in self.findings[:MAX_SECTION_ROWS]:
                missing = markdown_cell(", ".join(f.missing))
                body.append(
                    f"| `{markdown_cell(f.name)}` | `{markdown_cell(f.path)}:{f.line}` | {f.kind} | {missing} |"
                )
            if count > MAX_SECTION_ROWS:
                body += ["", f"... and {count - MAX_SECTION_ROWS} more in the job log."]
            body.append("")
        if self.any_delta > 0:
            body.append(
                f"The diff adds {self.any_delta} more `Any` than it removes. Where the shape is known, "
                "a dataclass or TypedDict says more. `Any` for a JSON payload is fine."
            )
        if self.ignore_delta > 0:
            body.append(f"The diff adds {self.ignore_delta} more type ignore comments than it removes.")

        status = "alert" if new_file_count else "warn" if count else "info"
        return {"status": status, "summary": ", ".join(summary), "body": "\n".join(body)}

    def to_json(self, blocking_from: date | None) -> str:
        return json.dumps(
            {
                "findings": [asdict(f) for f in self.findings],
                "any_delta": self.any_delta,
                "ignore_delta": self.ignore_delta,
                "new_file_blocking": bool(blocking_from and is_blocking(blocking_from)),
                "section": self.ci_section(blocking_from),
            },
            indent=1,
        )


def is_checked_path(path: str) -> bool:
    parts = PurePosixPath(path).parts
    name = parts[-1]
    if not name.endswith(".py") or parts[0] not in CHECKED_ROOTS:
        return False
    if name.startswith("test_") or name.endswith("_test.py") or name == "conftest.py":
        return False
    return not SKIPPED_PARTS.intersection(parts)


def parse_diff(diff: str) -> tuple[list[FileChange], list[str]]:
    """Return the changed files and every removed line, including lines from deleted files."""
    files: list[FileChange] = []
    all_removed: list[str] = []
    current: FileChange | None = None
    is_new = False
    old_path = ""
    # Header lines come before a file's first hunk. After it, "--- x" is a removed line that starts with "-- ".
    in_header = False
    line_no = 0
    for raw in diff.splitlines():
        if raw.startswith("diff --git "):
            current = None
            is_new = False
            in_header = True
            continue
        hunk = HUNK_HEADER.match(raw)
        if hunk:
            in_header = False
            line_no = int(hunk.group(1))
            if current and hunk.group(2) == "0":
                current.deleted_after.append(line_no)
            continue
        if in_header:
            if raw.startswith("new file mode"):
                is_new = True
            elif raw.startswith("--- "):
                old_path = raw[4:].removeprefix("a/")
            elif raw.startswith("+++ "):
                # A deleted file is kept so its removed lines still count in the Any and ignore deltas.
                if raw[4:] == "/dev/null":
                    current = FileChange(path=old_path, is_deleted=True)
                else:
                    current = FileChange(path=raw[4:].removeprefix("b/"), is_new=is_new)
                files.append(current)
            continue
        if raw.startswith("-"):
            all_removed.append(raw[1:])
            if current:
                current.removed.append(raw[1:])
            continue
        if raw.startswith("+") and current:
            current.added[line_no] = raw[1:]
            line_no += 1
    return files, all_removed


def decorator_names(node: ast.FunctionDef | ast.AsyncFunctionDef) -> set[str]:
    names = set()
    for decorator in node.decorator_list:
        target = decorator.func if isinstance(decorator, ast.Call) else decorator
        if isinstance(target, ast.Name):
            names.add(target.id)
        elif isinstance(target, ast.Attribute):
            names.add(target.attr)
    return names


def noqa_rules(match: re.Match[str] | None) -> frozenset[str]:
    if not match:
        return frozenset()
    codes = match.group("codes")
    if codes is None:
        return ALL_RULES
    return frozenset(code.strip().upper() for code in codes.split(","))


def file_exempt_rules(source: str) -> frozenset[str]:
    return frozenset().union(*(noqa_rules(match) for match in FILE_NOQA.finditer(source)))


@dataclass(frozen=True)
class FunctionSpan:
    node: ast.FunctionDef | ast.AsyncFunctionDef
    start: int
    end: int
    is_method: bool
    is_nested: bool

    @property
    def return_rule(self) -> str:
        """The ruff rule that covers this function's return annotation."""
        name = self.node.name
        if name.startswith("__") and name.endswith("__"):
            return "ANN204"
        if name.startswith("_") or self.is_nested:
            return "ANN202"
        return "ANN201"


def missing_annotations(span: FunctionSpan, lines: list[str], file_exempt: frozenset[str]) -> list[str]:
    node = span.node
    decorators = decorator_names(node)
    positional = [*node.args.posonlyargs, *node.args.args]
    if span.is_method and "staticmethod" not in decorators and positional:
        positional = positional[1:]
    missing = [
        f"parameter `{arg.arg}`"
        for arg in [*positional, *node.args.kwonlyargs]
        if arg.annotation is None and "ANN001" not in file_exempt | noqa_rules(LINE_NOQA.search(lines[arg.lineno - 1]))
    ]
    # ruff checks static and class method returns under ANN205 and ANN206, which the products config leaves off.
    if (
        node.returns is None
        and not decorators.intersection({"staticmethod", "classmethod"})
        and span.return_rule not in file_exempt | noqa_rules(LINE_NOQA.search(lines[node.lineno - 1]))
    ):
        missing.append("return type")
    return missing


class FunctionCollector(ast.NodeVisitor):
    """Collect every function with its line span, skipping overloads the way ruff does."""

    def __init__(self) -> None:
        self.spans: list[FunctionSpan] = []
        self._in_class: list[bool] = [False]
        self._in_function: list[bool] = [False]
        self._overloaded: list[set[str]] = [set()]

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        self._enter_scope(node, in_class=True, in_function=self._in_function[-1])

    def visit_FunctionDef(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
        overloaded = self._overloaded[-1]
        if "overload" in decorator_names(node):
            overloaded.add(node.name)
        elif node.name not in overloaded:
            start = min([node.lineno, *(d.lineno for d in node.decorator_list)])
            end = node.end_lineno or node.lineno
            self.spans.append(FunctionSpan(node, start, end, self._in_class[-1], self._in_function[-1]))
        self._enter_scope(node, in_class=False, in_function=True)

    visit_AsyncFunctionDef = visit_FunctionDef

    def _enter_scope(self, node: ast.AST, in_class: bool, in_function: bool) -> None:
        self._in_class.append(in_class)
        self._in_function.append(in_function)
        self._overloaded.append(set())
        self.generic_visit(node)
        self._in_class.pop()
        self._in_function.pop()
        self._overloaded.pop()


def innermost(spans: list[FunctionSpan], first: int, last: int) -> FunctionSpan | None:
    containing = [s for s in spans if s.start <= first and last <= s.end]
    return min(containing, key=lambda s: s.end - s.start, default=None)


def check_file(change: FileChange, source: str, moved_lines: set[str]) -> list[Finding] | None:
    """Return the findings for one changed file, or None when the file does not parse."""
    lines = source.splitlines()
    header_comments = "\n".join(line for line in lines[:15] if line.lstrip().startswith("#"))
    if GENERATED_HEADER.search(header_comments):
        return []
    file_exempt = file_exempt_rules(source)
    if file_exempt >= ALL_RULES:
        return []
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return None
    collector = FunctionCollector()
    collector.visit(tree)

    touched: dict[int, list[str]] = {}
    for line, text in change.added.items():
        span = innermost(collector.spans, line, line)
        if span and text.strip():
            touched.setdefault(span.node.lineno, []).append(text.strip())
    # A deletion between two lines of a function edits it, even when the hunk adds nothing.
    for line in change.deleted_after:
        span = innermost(collector.spans, line, line + 1)
        if span:
            touched.setdefault(span.node.lineno, [])

    removed_defs = {match.group(1) for line in change.removed if (match := REMOVED_DEF.match(line))}
    findings = []
    for span in collector.spans:
        added = touched.get(span.node.lineno)
        if added is None:
            continue
        missing = missing_annotations(span, lines, file_exempt)
        if not missing:
            continue
        # A whole signature that also appears among the removed lines may belong to an old function that moved.
        signature_end = max(span.node.lineno, span.node.body[0].lineno - 1)
        signature = [line.strip() for line in lines[span.node.lineno - 1 : signature_end]]
        signature_moved = all(line in moved_lines for line in signature if line)
        def_added = span.node.lineno in change.added
        # Only a function that re-adds its signature can be a move, so a body edit that happens to repeat
        # a line removed elsewhere still counts.
        if def_added and signature_moved and all(text in moved_lines for text in added):
            continue
        # A shared signature such as `def __init__(self):` proves nothing alone, so a move also needs body lines.
        body = [text for text in added if text not in signature]
        moved_body = sum(text in moved_lines for text in body)
        moved_with_edits = signature_moved and moved_body > 0 and moved_body * 2 >= len(body)
        if not def_added or moved_with_edits or span.node.name in removed_defs:
            kind = "edited"
        elif change.is_new:
            kind = "new file"
        else:
            kind = "new"
        findings.append(Finding(change.path, span.node.lineno, span.node.name, kind, missing))
    return findings


def git(*args: str) -> str:
    return subprocess.run(
        ["git", *args], capture_output=True, text=True, encoding="utf-8", errors="replace", check=True
    ).stdout


def count_matches(pattern: re.Pattern[str], texts: list[str]) -> int:
    return sum(len(pattern.findall(text)) for text in texts)


def build_report(diff: str, read_source: Callable[[str], str | None]) -> Report:
    files, all_removed = parse_diff(diff)
    moved_lines = {line.strip() for line in all_removed if line.strip()}
    checked = [f for f in files if is_checked_path(f.path)]

    findings: list[Finding] = []
    unparsed: list[str] = []
    for change in checked:
        source = None if change.is_deleted else read_source(change.path)
        if source is None:
            continue
        file_findings = check_file(change, source, moved_lines)
        if file_findings is None:
            unparsed.append(change.path)
        else:
            findings.extend(file_findings)

    # Moved lines appear on both sides of the diff, so they drop out of the Any and ignore counts.
    all_added = {text.strip() for f in files for text in f.added.values()}
    added_text = [text for f in checked for text in f.added.values() if text.strip() not in moved_lines]
    removed_text = [text for f in checked for text in f.removed if text.strip() not in all_added]
    any_delta = count_matches(ANY_TOKEN, added_text) - count_matches(ANY_TOKEN, removed_text)
    ignore_delta = count_matches(IGNORE_COMMENT, added_text) - count_matches(IGNORE_COMMENT, removed_text)
    return Report(findings, any_delta, ignore_delta, unparsed)


def source_reader(revision: str) -> Callable[[str], str | None]:
    def read(path: str) -> str | None:
        try:
            return git("show", f"{revision}{path}")
        except subprocess.CalledProcessError:
            return None

    return read


def emit(text: str, stream: TextIO | None = None) -> None:
    (stream or sys.stdout).write(text + "\n")


def describe(finding: Finding) -> str:
    return f"  {finding.path}:{finding.line}  {finding.name}  ({finding.kind}; missing {', '.join(finding.missing)})"


def print_commit_warning(report: Report) -> None:
    out = sys.stderr
    if report.unparsed:
        emit(
            f"\nThe typing check skipped {len(report.unparsed)} file(s) that Python "
            f"{sys.version_info.major}.{sys.version_info.minor} cannot parse. Run the hook with the project venv "
            "to check them.",
            out,
        )
    if not report.findings and report.any_delta <= 0 and report.ignore_delta <= 0:
        return
    if report.findings:
        count = len(report.findings)
        emit(
            f"\n\033[33mWarning: this commit touches {count} Python function{'s' if count != 1 else ''} without full annotations.\033[0m",
            out,
        )
        for finding in report.findings[:MAX_LISTED]:
            emit(describe(finding), out)
        if count > MAX_LISTED:
            emit(f"  ... and {count - MAX_LISTED} more", out)
    if report.any_delta > 0:
        emit(
            f"\nThis commit adds {report.any_delta} more `Any` than it removes. Where the shape is known, use a "
            "dataclass or TypedDict instead (see /writing-dataclasses). `Any` for a JSON payload is fine.",
            out,
        )
    if report.ignore_delta > 0:
        emit(f"\nThis commit adds {report.ignore_delta} more type ignore comments than it removes.", out)
    emit("\nIf you are an AI coding agent, this warning is addressed to you.", out)
    emit("Annotate every listed function now: each parameter and the return type.", out)
    emit("The same check runs in the PR's CI report, and a function in a new file fails CI.", out)
    emit("The commit still goes through.\n", out)


def escape_annotation_data(value: str) -> str:
    return value.replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A")


def escape_annotation_property(value: str) -> str:
    # A path is author-controlled, so ":" and "," must not end the property list of the workflow command.
    return escape_annotation_data(value).replace(":", "%3A").replace(",", "%2C")


def print_github_annotations(report: Report) -> None:
    for finding in report.findings:
        path = escape_annotation_property(finding.path)
        title = escape_annotation_property(f"Untyped function ({finding.kind})")
        message = escape_annotation_data(f"`{finding.name}` is missing {', '.join(finding.missing)}")
        emit(f"::warning file={path},line={finding.line},title={title}::{message}")


def enforce_new_files(report_path: str) -> int:
    with open(report_path) as fh:
        report = json.load(fh)
    new_file_findings = [Finding(**f) for f in report["findings"] if f["kind"] == "new file"]
    if not new_file_findings:
        return 0
    emit("Functions in new files need full annotations:")
    for finding in new_file_findings:
        emit(describe(finding))
    if not report["new_file_blocking"]:
        emit("The blocking date has not come yet, so this only warns.")
        return 0
    return 1


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--staged", action="store_true", help="check the staged diff and print a commit warning")
    mode.add_argument("--base", help="check the diff from this revision to HEAD")
    mode.add_argument("--enforce", metavar="REPORT", help="fail when a report lists functions in new files")
    parser.add_argument("--report", help="write the findings as JSON to this path")
    parser.add_argument("--github", action="store_true", help="print GitHub Actions annotations")
    parser.add_argument(
        "--blocking-from", type=date.fromisoformat, help="first day (UTC) that new-file findings fail --enforce"
    )
    args = parser.parse_args()

    if args.enforce:
        return enforce_new_files(args.enforce)

    # Explicit prefixes and no external diff, so a user's git config cannot change what parse_diff reads.
    diff_args = ["diff", "-U0", "--find-renames", "--no-color", "--no-ext-diff", "--src-prefix=a/", "--dst-prefix=b/"]
    if args.staged:
        diff = git(*diff_args, "--cached", "--", "*.py")
        report = build_report(diff, source_reader(":"))
        print_commit_warning(report)
        return 0

    diff = git(*diff_args, args.base, "HEAD", "--", "*.py")
    report = build_report(diff, source_reader("HEAD:"))
    if args.report:
        with open(args.report, "w") as fh:
            fh.write(report.to_json(args.blocking_from))
    if args.github:
        print_github_annotations(report)
    for finding in report.findings:
        emit(describe(finding))
    emit(f"Any delta: {report.any_delta:+d}, ignore comment delta: {report.ignore_delta:+d}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
